public class RotatedArraySearch { public static void main(String[] args) { int[] arr = {4,5,6,7,1,2,3}; int target = 2; int low = 0; int high = arr.length - 1; int index = -1; while (low <= high) { int mid = (low + high) / 2; if (arr[mid] == target) { index = mid; break; } if (arr[low] <= arr[mid]) { if (target >= arr[low] && target < arr[mid]) { high = mid - 1; } else { low = mid + 1; } } else { if (target > arr[mid] && target <= arr[high]) { low = mid + 1; } else { high = mid - 1; } } } System.out.println("Index = " + index); } }
